import React from 'react';
import {Audio, Sequence, staticFile, useVideoConfig} from 'remotion';
import type {Scene} from '../types';

// SFX RULE: every template gets its sound automatically.
// cut → whoosh · title / crimson switch / big number → impact · photo → shutter + typewriter
// headline / document / newspaper → paper · cards / timeline dots / map pins / split boxes → tick
// All sounds are generated by tools/make-sfx.sh, so they're original (no copyright issues).

type Hit = {at: number; file: string; vol: number};

const hitsFor = (s: Scene, dur: number, index: number, prevMood?: Scene['mood']): Hit[] => {
  const h: Hit[] = [];
  if (index > 0) h.push({at: 0, file: 'whoosh', vol: 0.18});
  const moodHit = prevMood && prevMood !== s.mood && s.mood === 'danger';
  switch (s.template) {
    case 'title':
      h.push({at: 0, file: 'impact', vol: 0.42});
      break;
    case 'photos':
      s.photos.forEach((_, i) => {
        h.push({at: 4 + i * 9, file: 'shutter', vol: 0.5});
        h.push({at: 16 + i * 9, file: 'typewriter', vol: 0.3});
      });
      break;
    case 'headline': case 'document': case 'newspaper': case 'tweet':
      h.push({at: 2, file: 'paper', vol: 0.55});
      break;
    case 'stat':
      s.parts.forEach((_, i) => {
        const last = i === s.parts.length - 1;
        h.push({at: 6 + i * 14, file: last ? 'impact' : 'tick', vol: last ? 0.32 : 0.45});
      });
      break;
    case 'cards':
      s.cards.forEach((_, i) => h.push({at: Math.round((i / s.cards.length) * dur * 0.8) + 4, file: 'tick', vol: 0.45}));
      break;
    case 'timeline': {
      const n = s.points.length;
      s.points.forEach((_, i) => h.push({at: 6 + Math.round((i / Math.max(1, n)) * Math.min(dur * 0.7, n * 18)), file: 'tick', vol: 0.45}));
      break;
    }
    case 'map':
      (s.pins ?? []).forEach((_, i) => h.push({at: 8 + i * 10, file: 'tick', vol: 0.4}));
      break;
    case 'split':
      h.push({at: 4, file: 'tick', vol: 0.4}, {at: 12, file: 'tick', vol: 0.4}, {at: 22, file: 'tick', vol: 0.5});
      break;
  }
  if (moodHit && s.template !== 'title') h.push({at: 0, file: 'impact', vol: 0.28});
  return h.filter((x) => x.at < dur);
};

export const SceneSfx: React.FC<{scene: Scene; index: number; prevMood?: Scene['mood']}> = ({scene, index, prevMood}) => {
  const {durationInFrames} = useVideoConfig();
  return (
    <>
      {hitsFor(scene, durationInFrames, index, prevMood).map((x, i) => (
        <Sequence key={i} from={x.at} layout="none">
          <Audio src={staticFile(`sfx/${x.file}.wav`)} volume={x.vol} />
        </Sequence>
      ))}
    </>
  );
};

// Quiet dark drone under the whole video
export const Bed: React.FC = () => <Audio src={staticFile('sfx/drone.wav')} volume={0.09} loop />;
